<?php
require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;use MongoDB\BSON\UTCDateTime;
setJsonResponse();handleCors();logRequest();requireCustomer();
try{$db=getDatabase();$users=$db->users;$id=new ObjectId($_SESSION['user_id']);
 if($_SERVER['REQUEST_METHOD']==='GET'){$u=$users->findOne(['_id'=>$id]);if(!$u)sendResponse(false,'Profile not found.',null,404);sendResponse(true,'Profile loaded',['name'=>$u['name']??'','email'=>$u['email']??'','phone'=>$u['phone']??'','license'=>$u['license']??'','address'=>$u['address']??'','role'=>'user']);}
 if($_SERVER['REQUEST_METHOD']==='PUT'){$d=json_decode(file_get_contents('php://input'),true);$name=trim($d['name']??'');$phone=preg_replace('/\s+/','',trim($d['phone']??''));$license=trim($d['license']??'');$address=trim($d['address']??'');if(strlen($name)<2)sendResponse(false,'Please enter a valid name.',null,400);if($phone!==''&&!preg_match('/^[0-9]{10,15}$/',$phone))sendResponse(false,'Please enter a valid phone number.',null,400);$users->updateOne(['_id'=>$id],['$set'=>['name'=>$name,'phone'=>$phone,'license'=>$license,'address'=>$address,'updatedAt'=>new UTCDateTime()]]);$_SESSION['user_name']=$name;sendResponse(true,'Profile updated successfully.');}
 sendResponse(false,'Method not allowed.',null,405);
}catch(Throwable $e){error_log('Profile: '.$e->getMessage());sendResponse(false,'Profile operation failed.',null,500);}
